source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    def line_separators(axis):
        n = h if axis == 0 else w
        m = w if axis == 0 else h
        result = []
        for i in range(n):
            vals = [grid[i][j] for j in range(m)] if axis == 0 else [grid[j][i] for j in range(m)]
            if vals[0] != 0 and all(v == vals[0] for v in vals):
                result.append(i)
        return result
    def regions(n, lines):
        cuts = [-1] + lines + [n]
        return [(cuts[i]+1, cuts[i+1]) for i in range(len(cuts)-1)]
    row_regions = regions(h, line_separators(0))
    col_regions = regions(w, line_separators(1))
    # Use only complete, equally sized panels.
    row_sizes = [b-a for a,b in row_regions]
    col_sizes = [b-a for a,b in col_regions]
    rh = max(set(row_sizes), key=row_sizes.count)
    cw = max(set(col_sizes), key=col_sizes.count)
    row_regions = [(a,b) for a,b in row_regions if b-a == rh]
    col_regions = [(a,b) for a,b in col_regions if b-a == cw]
    def panel_cells(rr, cc):
        ra, rb = row_regions[rr]; ca, cb = col_regions[cc]
        return {(r-ra,c-ca): grid[r][c] for r in range(ra,rb) for c in range(ca,cb) if grid[r][c] != 0}
    def vflip(cells):
        return {(rh-1-r,c):v for (r,c),v in cells.items()}
    def hflip(cells):
        return {(r,cw-1-c):v for (r,c),v in cells.items()}
    # A horizontally mirrored pair of panels is a motif; copy its vertical
    # reflection into the neighboring row where one panel is already present.
    for rr in range(len(row_regions)):
        for cc in range(len(col_regions)-1):
            left, right = panel_cells(rr,cc), panel_cells(rr,cc+1)
            if not left or hflip(left) != right:
                continue
            choices=[]
            for target in (rr-1,rr+1):
                if 0 <= target < len(row_regions):
                    nmatch = sum(panel_cells(target,c) == vflip(panel_cells(rr,c)) for c in (cc,cc+1))
                    npartial = sum(bool(panel_cells(target,c)) for c in (cc,cc+1))
                    choices.append((nmatch, npartial, target))
            if not choices:
                continue
            # Prefer the adjacent band with a matching partial copy; otherwise
            # complete the pair below the seed.
            bestmatch=max(x[0] for x in choices)
            if bestmatch:
                target=max((x for x in choices if x[0]==bestmatch),key=lambda x:(x[1], -x[2]))[2]
            else:
                target=rr+1 if rr+1 < len(row_regions) else rr-1
            for c in (cc,cc+1):
                ra,rb=row_regions[target]; ca,cb=col_regions[c]
                for (r,x),v in vflip(panel_cells(rr,c)).items():
                    gr,gc=ra+r,ca+x
                    if out[gr][gc] == 0:
                        out[gr][gc]=v
    return out
